pub fn capture_frame() -> Result<Frame, Error> {
    // Uses Windows Graphics Capture API for zero-copy access
    let item = monitor.create_capture_item()?;
    let frame = item.capture_next_frame()?;

    if frame.diff(last_frame) > THRESHOLD {
         // Only run heavy OCR if content changed
         ocr_thread.send(frame);
    }
}

pub fn compile_node(node: &Node, context: &mut Context) -> String {
    match node.kind {
        NodeKind::DbQuery => {
             format!("const data = await prisma.{}.findMany({{ where: {} }});", 
             node.table, node.filters)
        },
        NodeKind::Condition => {
             // Recursively compile branches
             let true_branch = compile_branch(&node.true_id);
             format!("if ({}) {{ {} }}", node.condition, true_branch)
        }
    }
}

