const onPacketReceived = (packet) => {
  const { recipientId, messageId, ttl } = decode(packet);

  if (recipientId === MY_ID) {
      showNotification(packet.payload);
  } else if (ttl > 0 && !seenParams.has(messageId)) {
      // Not for me, forward it to neighbors
      seenParams.add(messageId);
      addToRelayQueue(packet);
      decrementTTL(packet);
  }
